exports.handler = async (event) => {
  const record = JSON.parse(Buffer.from(event.data, 'base64').toString());
  const tenant = record.tenantId;
  const key = `tenants/${tenant}/${record.eventTime}.parquet`;
  // write to S3 with tenant-specific CMK context (enforced by bucket policy)
  await s3.putObject({ Bucket: bucketName, Key: key, Body: parquetBuffer }).promise();
  // write audit entry
  await dyno.putItem({ TableName: auditTable, Item: { tenant, eventId: record.id, ts: Date.now() } }).promise();
};
